// DEMO ONLY: LoopCasts has no real bank connection in this project, so this makes the file the
// bank would give us: today's incoming payments for the newest open invoices, in KBC's CSV format.
//   newest invoice:  paid with the structured reference (the normal case)
//   second newest:   reference forgotten, invoice number typed in the message
//   third newest:    paid 20 euro too little
// plus one outgoing payment and one payment that is not for an invoice at all.
const invoices = $input.all().map((i) => i.json).filter((i) => i.id);
const now = new Date();
const p = (n) => String(n).padStart(2, '0');
const today = `${p(now.getDate())}/${p(now.getMonth() + 1)}/${now.getFullYear()}`;
const money = (n) => n.toFixed(2).replace('.', ',');
let balance = 24850.12;
const rows = ['Rekeningnummer;Datum;Bedrag;Munt;Naam tegenpartij;Rekening tegenpartij;Vrije mededeling;Saldo'];
const add = (amount, name, iban, message) => {
  balance = Math.round((balance + amount) * 100) / 100;
  rows.push(['BE68 5390 0754 7034', today, money(amount), 'EUR', name, iban, message, money(balance)].join(';'));
};
const iban = (id) => `BE${String(10 + (id % 89)).padStart(2, '0')}${String(id * 7919).padStart(12, '0').slice(-12)}`;

add(-75, 'VIMEO.COM', 'BE11846073157418', 'Vimeo Pro yearly');
invoices.slice(0, 3).forEach((inv, k) => {
  const total = Number(inv.total);
  if (k === 0) add(total, inv.customer_name, iban(inv.id), inv.ogm);
  if (k === 1) add(total, String(inv.customer_name).toUpperCase(), iban(inv.id), `factuur ${inv.number}`);
  if (k === 2) add(Math.round((total - 20) * 100) / 100, inv.customer_name, iban(inv.id), inv.ogm);
});
add(42.5, 'Pieter Claes', 'BE71096123456769', 'terugbetaling lunch');

const stamp = `${now.getFullYear()}-${p(now.getMonth() + 1)}-${p(now.getDate())} ${p(now.getHours())}${p(now.getMinutes())}${p(now.getSeconds())}`;
return [{ json: { fileName: `KBC export demo ${stamp}.csv`, csv: rows.join('\r\n') + '\r\n' } }];
